#include <string>
#include <vector>

void hanoi(int discs, char from, char to, char spare, std::vector<std::string>& moves)
{
    if (discs == 0)
    {
        return;
    }
    hanoi(discs - 1, from, spare, to, moves);
    moves.push_back(std::string{ from } + "->" + to);
    hanoi(discs - 1, spare, to, from, moves);
}

unitTests:
TEST("one disc") { std::vector<std::string> m; hanoi(1, 'A', 'C', 'B', m); CHECK_EQ(m, (std::vector<std::string>{ "A->C" })); }
TEST("two discs") { std::vector<std::string> m; hanoi(2, 'A', 'C', 'B', m); CHECK_EQ(m, (std::vector<std::string>{ "A->B", "A->C", "B->C" })); }
TEST("three discs") { std::vector<std::string> m; hanoi(3, 'A', 'C', 'B', m); CHECK_EQ(m, (std::vector<std::string>{ "A->C", "A->B", "C->B", "A->C", "B->A", "B->C", "A->C" })); }
TEST("ten discs take 1023 moves") { std::vector<std::string> m; hanoi(10, 'A', 'C', 'B', m); CHECK_EQ(m.size(), 1023u); }
TEST("no discs, no moves") { std::vector<std::string> m; hanoi(0, 'A', 'C', 'B', m); CHECK(m.empty()); }

